# ------------------------------ MARK ------------------------------
dict(id="H01", t=829, b=833, marks=25, diff="medium",
     q="Explain the parable of the sower and the interpretation which Jesus gave of it in Mark 4:1-20.",
     ideal=("The parable of the sower stands at the head of Mark's collection of parables depicting the character of God's kingdom, "
            "and the syllabus reads it as an explanation of the opposition Jesus met. The reason why Jesus was opposed by the religious "
            "leaders and others, including His own relations, was the spiritual condition of their hearts, and in the parable He urged His "
            "hearers to give careful consideration to the nature of their own hearts. Some hearers never understood or grasped His message "
            "at all; others were discouraged through difficulties; others again were seduced through prosperity; the result was that only a "
            "limited proportion became lastingly committed to it.\n\n"
            "Before explaining the parable Jesus answered the disciples' question as to why He employed parables. The essence of His reply is "
            "that He did so in order to test the spiritual responsiveness of His audience. Those provoked by the parables into intensive "
            "reflection could proceed to obtain enlightenment concerning them, while those who would not reflect on them could be ever seeing "
            "but never perceiving; that is, they would understand the literal meaning of the words but not the parable's deeper significance.\n\n"
            "In the interpretation the farmer, or sower, probably represents Jesus and all who sow or proclaim the word of God, which is the "
            "seed. The kinds of soil represent four different ways in which people respond to God's word, three of them negative. The first is "
            "hard-hearted indifference, where Satan, like the birds, comes immediately and takes the word away, so that in effect there is no "
            "response. The second is a hasty, enthusiastic but shallow profession of acceptance which lasts only a short time because the word "
            "takes no root; there is a lack of spiritual depth, and when trouble or persecution comes on account of the word such hearers quickly "
            "fall away, their profession proving not to be genuine. The third are those who hear the word but are preoccupied with the cares and "
            "riches of this life, which choke the word and make it unfruitful, indicating that they are not true believers. By contrast others hear "
            "the word, accept it - welcome it for themselves - and produce a crop. These are evidently genuine disciples who bear fruitful yields "
            "of varying amounts: thirty, sixty or a hundredfold."),
     keypoints=["The parable explains the opposition Jesus met: the spiritual condition of the hearers' hearts",
                "Hearers are urged to consider the nature of their own hearts",
                "Jesus taught in parables to test the spiritual responsiveness of His audience",
                "Those who would not reflect would be ever seeing but never perceiving",
                "The sower represents Jesus and all who proclaim the word; the seed is the word of God",
                "Hard-hearted indifference: Satan, like the birds, takes the word away at once",
                "Shallow, rootless profession falls away when trouble or persecution comes",
                "Cares and riches choke the word and make it unfruitful",
                "Genuine disciples hear, accept and bear fruit thirty, sixty or a hundredfold"],
     rubric=[dict(id="c1", label="Purpose of the parable", description="Relates the parable to the spiritual condition of the hearts of those who opposed Jesus.", marks=5,
                  keywords=["spiritual condition", "hearts", "opposition", "religious leaders"],
                  syn=[["spiritual condition", "state of the heart", "condition of their hearts"], ["opposed", "opposition", "rejected"]], required=True),
             dict(id="c2", label="Why Jesus used parables", description="Explains that parables tested the spiritual responsiveness of the audience, so that some see but never perceive.", marks=5,
                  keywords=["test", "spiritual responsiveness", "seeing", "perceiving", "deeper significance"],
                  syn=[["test", "prove", "try"], ["responsiveness", "response", "receptiveness"]], required=True),
             dict(id="c3", label="The sower and the seed", description="Identifies the sower with Jesus and all who proclaim the word, and the seed with the word of God.", marks=4,
                  keywords=["sower", "farmer", "seed", "word of God", "proclaim"],
                  syn=[["sower", "farmer"], ["proclaim", "preach", "sow"]], required=True),
             dict(id="c4", label="The three negative responses", description="Describes hard-hearted indifference, shallow rootless profession, and preoccupation with cares and riches.", marks=7,
                  keywords=["indifference", "Satan", "birds", "shallow", "root", "persecution", "cares", "riches", "choke"],
                  syn=[["indifference", "hard-hearted", "hardness"], ["persecution", "trouble", "hardship"], ["choke", "smother", "make unfruitful"]], required=True),
             dict(id="c5", label="The fruitful soil", description="Describes genuine disciples who hear, accept and bear fruit thirtyfold, sixtyfold and a hundredfold.", marks=4,
                  keywords=["accept", "welcome", "crop", "fruit", "30", "60", "100", "thirty", "sixty", "hundred"],
                  syn=[["accept", "welcome", "receive"], ["crop", "fruit", "harvest", "yield"]], required=True)],
     expl="This question tests whether the candidate can reproduce both the parable's purpose and the fourfold interpretation exactly as the syllabus gives them.",
     exc="Some hearers of his teaching, according to Him, never understood (grasped) His message at all; others were discouraged through difficulties, and others again were seduced through prosperity; the result was that only a limited proportion became lastingly committed to it.",
     scr=[], tags=["mark", "parables", "sower"]),

dict(id="H02", t=1081, b=1083, marks=25, diff="medium",
     q="Give an account of Jesus' teaching on marriage and divorce in Mark 10:1-12, and explain why He referred the Pharisees back to the creation.",
     ideal=("The syllabus stresses that the question put by the Pharisees was malicious. It was put to Jesus in order to test Him, that is, to "
            "try to induce Him to incriminate Himself by contradicting the Mosaic Law. The Mosaic enactment of Deuteronomy 24:1-4 stated that a "
            "husband was allowed to divorce his wife by writing and giving to her a certificate of divorce if he had found some unseemly thing in "
            "her, and the whole question turned upon what constituted an unseemly thing.\n\n"
            "Shammai and Hillel were the authorities in the interpretation of the Mosaic Law, and different groups took their authority from them. "
            "The school of Shammai maintained the strict interpretation, holding that the marriage band was indissoluble except in the event of the "
            "wife's infidelity. The school of Hillel took the liberal view, allowing divorce for almost any cause. To answer either school directly "
            "would have set Jesus against a recognised body of opinion, which is what His questioners intended.\n\n"
            "In reply Jesus first pointed out that Moses' legislation was a concession to human weakness, rightly introduced to regulate divorce in "
            "a defective state of society. He quoted the words, 'Because of the hardness of your heart he wrote to you this commandment.' Moses' "
            "provision was therefore not a divine ideal but a restraint upon an existing evil.\n\n"
            "Secondly, Jesus took the Pharisees back beyond Moses to God's ideal at the beginning of creation. From that ideal we discover that "
            "marriage was instituted as the divine ideal for man and woman, and that the bond is permanent and indissoluble. By going behind the "
            "concession to the creation ordinance Jesus set the discussion on a different footing altogether: the question is not how much divorce "
            "the Law will tolerate, but what God intended marriage to be from the beginning. The passage that follows, on receiving the kingdom in "
            "childlike trust, continues the same emphasis upon the divine order rather than upon human casuistry."),
     keypoints=["The Pharisees' question was malicious, intended to make Jesus contradict the Mosaic Law",
                "Deuteronomy 24:1-4 allowed a certificate of divorce for 'some unseemly thing'",
                "The debate turned on what constituted an unseemly thing",
                "Shammai held the bond indissoluble except for the wife's infidelity",
                "Hillel allowed divorce for almost any cause",
                "Jesus replied that Moses' legislation was a concession to human weakness",
                "'Because of the hardness of your heart he wrote to you this commandment'",
                "Jesus took them back beyond Moses to God's ideal at creation: the bond is permanent and indissoluble"],
     rubric=[dict(id="c1", label="The malicious question", description="Shows that the Pharisees intended to induce Jesus to contradict the Mosaic Law.", marks=4,
                  keywords=["malicious", "test", "incriminate", "Mosaic Law", "contradict"],
                  syn=[["malicious", "hostile", "designed to trap"], ["test", "tempt", "try"]], required=True),
             dict(id="c2", label="The Mosaic enactment", description="States the provision of Deuteronomy 24:1-4 and the dispute over 'some unseemly thing'.", marks=5,
                  keywords=["certificate of divorce", "unseemly thing", "Deuteronomy", "husband"],
                  syn=[["certificate of divorce", "bill of divorcement", "writing of divorce"], ["unseemly thing", "indecency", "something unseemly"]], required=True),
             dict(id="c3", label="Shammai and Hillel", description="Distinguishes the strict school of Shammai from the liberal school of Hillel.", marks=6,
                  keywords=["Shammai", "Hillel", "strict", "liberal", "infidelity", "any cause"],
                  syn=[["strict", "rigorous", "narrow"], ["liberal", "lax", "permissive"], ["infidelity", "adultery", "unfaithfulness"]], required=True),
             dict(id="c4", label="Moses' concession", description="Explains that the legislation was a concession to human weakness because of hardness of heart.", marks=5,
                  keywords=["concession", "human weakness", "hardness of your heart", "regulate", "defective"],
                  syn=[["concession", "allowance", "accommodation"], ["hardness of heart", "hard-heartedness"]], required=True),
             dict(id="c5", label="God's ideal at creation", description="Shows that Jesus went behind Moses to creation, where the bond is permanent and indissoluble.", marks=5,
                  keywords=["creation", "divine ideal", "permanent", "indissoluble", "beginning"],
                  syn=[["divine ideal", "God's ideal", "God's intention"], ["indissoluble", "unbreakable", "permanent"]], required=True)],
     expl="The question tests both the historical background the syllabus supplies (Shammai and Hillel) and the two steps of Jesus' reply.",
     exc="The school of Shammai maintained the strict interpretation of this, that the marriage band was indissoluble except in the event of the wife's infidelity. The school of Hillel took the liberal view allowing divorce for almost any cause (v. 5).",
     scr=[], tags=["mark", "marriage", "divorce"]),

dict(id="H03", t=1202, b=1257, marks=25, diff="hard",
     q="Give an account of the trial of Jesus before the Sanhedrin as presented in Mark 14:53-65.",
     ideal=("The syllabus explains that this trial by the Sanhedrin, the Jewish Supreme Court, had two phases: a small group met at night and the "
            "full Council met at daybreak. Jesus was tried for religious offences such as calling Himself the Son of God, which according to the Law "
            "was blasphemy. The trial was obviously fixed, because these religious leaders had already decided to kill Jesus.\n\n"
            "The Sanhedrin began their deliberations by seeking evidence against Jesus in order to justify a death sentence, but they found none. "
            "Many witnesses testified falsely, but their testimonies did not corroborate. In Jewish trials the witnesses served as the prosecution and "
            "gave their testimonies separately, and to convict a person the Mosaic Law required precise agreement in the testimony of at least two "
            "witnesses.\n\n"
            "The claim on which the false witnesses finally agreed twisted Jesus' actual words. He did not say, 'I will destroy this Temple'; He said, "
            "'Destroy this temple and in three days I will raise it up', and He was speaking not about Herod's Temple but about His own death and "
            "resurrection. To this first accusation Jesus gave no response, because the evidence itself was confusing and erroneous, and not answering "
            "was wiser than trying to clarify fabricated accusations.\n\n"
            "The high priest then asked, 'Are you the Christ, the Son of the Blessed One?' To refuse to answer this would have been taken as a denial "
            "of His mission. Jesus' answer predicted a powerful role-reversal: sitting at the right hand of God meant that He would come to judge them "
            "and that they would be answering questions. By tearing his clothes the high priest showed that he regarded this bold declaration as "
            "blasphemy; this symbolic expression of horror and indignation was required of the high priest whenever he heard blasphemy, and his "
            "reaction also expressed relief, since Jesus' self-incriminating answer removed the need for more witnesses. Without further investigation "
            "the high priest called for a verdict, and since there were no objections they all condemned Him as worthy of death. Thereafter some members "
            "showed their contempt through mockery and physical abuse, spat in His face - an act of gross personal insult - blindfolded Him on account "
            "of His messianic claims, struck Him with their fists and demanded that He prophesy who hit Him."),
     keypoints=["The trial had two phases: a small group at night, the full Council at daybreak",
                "The charge was religious - calling Himself the Son of God, which was blasphemy",
                "The trial was fixed: the leaders had already decided to kill Jesus",
                "Witnesses served as the prosecution; the Law required precise agreement of at least two",
                "The false witnesses twisted Jesus' words about destroying the temple",
                "Jesus was silent on the temple charge because the evidence was confusing and erroneous",
                "He answered the high priest's question about the Christ, predicting a role-reversal",
                "The high priest tore his clothes, the required expression of horror at blasphemy",
                "All condemned Him as worthy of death; mockery and physical abuse followed"],
     rubric=[dict(id="c1", label="Constitution of the trial", description="Notes the two phases of the Sanhedrin trial and the religious nature of the charge.", marks=5,
                  keywords=["Sanhedrin", "two phases", "night", "daybreak", "blasphemy", "Son of God"],
                  syn=[["Sanhedrin", "Jewish Supreme Court", "Council"], ["daybreak", "morning", "dawn"]], required=True),
             dict(id="c2", label="A fixed trial", description="Shows that the leaders had already decided to kill Jesus.", marks=3,
                  keywords=["fixed", "already decided", "kill"],
                  syn=[["fixed", "rigged", "predetermined"]], required=False),
             dict(id="c3", label="The failure of the witnesses", description="Explains the requirement of at least two agreeing witnesses and the failure of the testimony to corroborate.", marks=5,
                  keywords=["witnesses", "false", "corroborate", "two witnesses", "prosecution"],
                  syn=[["corroborate", "agree", "tally"], ["false", "untrue", "fabricated"]], required=True),
             dict(id="c4", label="The temple saying", description="Shows how the words were twisted and that Jesus spoke of His own death and resurrection.", marks=5,
                  keywords=["destroy this temple", "three days", "raise it up", "death and resurrection", "Herod's Temple"],
                  syn=[["raise it up", "rebuild it"], ["death and resurrection", "his own body"]], required=True),
             dict(id="c5", label="The high priest's question and the verdict", description="Gives the question about the Christ, Jesus' answer, the tearing of the clothes and the condemnation.", marks=7,
                  keywords=["Are you the Christ", "right hand of God", "tearing his clothes", "blasphemy", "worthy of death", "mockery", "spat"],
                  syn=[["tearing his clothes", "tore his robes", "rent his garments"], ["worthy of death", "deserving death", "condemned"]], required=True)],
     expl="The question tests the candidate's grasp of the procedure of the trial and of the two accusations, together with the significance the syllabus attaches to each.",
     exc="The Sanhedrin began their deliberations by seeking evidence against Jesus in order to justify a death sentence but they found none.",
     scr=["Numbers 35:30", "Psalms 110:1"], tags=["mark", "passion", "sanhedrin", "trial"]),

dict(id="H04", t=1271, b=1304, marks=25, diff="hard",
     q="Describe the supernatural events which accompanied the death of Jesus in Mark 15 and explain the significance the syllabus attaches to them.",
     ideal=("Mark records five supernatural events that accompanied the death of Jesus: the darkness, Jesus' cry 'My God, my God', His loud cry, the "
            "tearing of the temple curtain from top to bottom, and the confession of the Roman centurion.\n\n"
            "Jesus hung on the cross for three hours in the daylight, from nine in the morning until noon, and then at the sixth hour total darkness "
            "engulfed the whole land, that is Palestine and its environs, until the ninth hour, three in the afternoon. The darkness was probably a "
            "cosmic sign of God's judgment on human sin, which was placed on Jesus. It visualised what His cry expressed.\n\n"
            "That cry, 'Eli, Eli, lama sabachthani', is the Aramaic form of the Hebrew of Psalm 22:1, and means 'My God, my God, why have you forsaken "
            "me?' The syllabus insists that this was more than a righteous sufferer affirming his faith that the Father would cause him to triumph. "
            "Jesus' cry combined abandonment by the Father in a judicial and not a relational sense, together with a genuine affirmation of His "
            "relationship to the Father. He was bearing the curse of sin and the Father's judgment upon sin, and experienced for the first time the "
            "horror of separation from God, who cannot look on sin and therefore hid His face. Although seemingly exhausted, Jesus was offered vinegar "
            "by the soldiers and then uttered a loud cry, after which He breathed His last.\n\n"
            "The tearing of the temple curtain carries its own significance. A heavy veil hung in front of the Holy of Holies, a place reserved by God "
            "for Himself, and it symbolically separated the Holy God from sinful mankind. The place was entered only once a year, on the Day of "
            "Atonement, by the High Priest as he made a sacrifice to gain forgiveness for the sins of all the people. When Jesus died the veil was split "
            "in two, showing that His death for our sins had opened the way for us to approach our Holy God. The centurion's confession completes the "
            "list, so that a Gentile soldier bears witness to what the religious leaders had denied."),
     keypoints=["Five supernatural events: darkness, the cry of dereliction, the loud cry, the torn curtain, the centurion's confession",
                "Darkness from the sixth hour (noon) to the ninth hour (3 pm) over the whole land",
                "The darkness was probably a cosmic sign of God's judgment on human sin placed on Jesus",
                "'Eli, Eli, lama sabachthani' - Aramaic for the Hebrew of Psalm 22:1",
                "The cry combined judicial (not relational) abandonment with a genuine affirmation of relationship",
                "Jesus bore the curse of sin and experienced separation from God who cannot look on sin",
                "The veil separated the Holy God from sinful mankind and was entered once a year on the Day of Atonement",
                "The torn veil shows that Jesus' death opened the way for us to approach our Holy God"],
     rubric=[dict(id="c1", label="The five events", description="Lists the five supernatural events Mark records.", marks=5,
                  keywords=["darkness", "cry", "loud cry", "curtain", "veil", "centurion"],
                  syn=[["curtain", "veil"], ["centurion", "Roman centurion", "soldier"]], required=True),
             dict(id="c2", label="The darkness", description="Gives the hours of the darkness and explains it as a cosmic sign of God's judgment on sin.", marks=6,
                  keywords=["sixth hour", "ninth hour", "noon", "3 pm", "judgment", "cosmic sign"],
                  syn=[["cosmic sign", "sign", "portent"], ["judgment", "judgement", "condemnation"]], required=True),
             dict(id="c3", label="The cry of dereliction", description="Gives the Aramaic words, their source in Psalm 22:1, and their meaning.", marks=6,
                  keywords=["Eli", "lama sabachthani", "Psalm 22", "forsaken", "Aramaic"],
                  syn=[["forsaken", "abandoned", "left"], ["Aramaic", "Aramaic words"]], required=True),
             dict(id="c4", label="Judicial abandonment", description="Explains abandonment in a judicial not relational sense, and the bearing of the curse of sin.", marks=4,
                  keywords=["judicial", "relational", "curse of sin", "separation", "cannot look on sin"],
                  syn=[["judicial", "legal", "forensic"], ["separation", "alienation"]], required=False),
             dict(id="c5", label="The torn veil", description="Explains the veil, the Day of Atonement, and the access to God opened by Jesus' death.", marks=4,
                  keywords=["Holy of Holies", "Day of Atonement", "High Priest", "approach", "split in two"],
                  syn=[["Holy of Holies", "most holy place"], ["approach", "come near", "access"]], required=True)],
     expl="The question tests both the factual list of events and the theological explanation the syllabus gives for the darkness, the cry and the veil.",
     exc="The darkness was probably a cosmic sign of God's judgment on human sin",
     scr=["Psalms 22:1", "2 Corinthians 5:21"], tags=["mark", "crucifixion", "atonement"]),

